from pathlib import Path
choices=[('Mevcut Ana Sayfa','Kökteki çalışan ekran; karşılaştırma kopyası.','mevcut-ana.html','Değişiklik yok. Webden gelen tüm bölümler ve davranışlar.','Yerel kopya; Püf Noktaları menü adı ve opak alt menü zemini.'),('1 · En sade','Tek yemek kararı, ardından üç kısa yol.','ana-1.html','Kategoriler, ayrı Günün Tarifi, ders, video, şef, Pro ve topluluk vitrinleri.','Hibrit; kısa Dolap girişi, mevcut büyük öne çıkan kartlar ve tek püf kartı.'),('2 · Modül kapıları','Beş ana modül, beş farklı giriş.','ana-2.html','Web vitrinleri ve pazarlama; diğer ürünler kapsam haritasındaki yerlere.','Hibrit; fotoğraflı Tarifler, tercih aracı, Dolap seçimi, Püf girişi ve kamera kartı.'),('3 · İçerik akışı','Kompakt yolların ardından tarif ve bilgi rafları.','ana-3.html','Web vitrinleri, sayaç ve tekrarlanan etiketler.','Hibrit; beşli şerit, ortak tarif rafı ve püf rafı; yalnız kayıt varsa devam.')]
s='''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>DadaGastro · Ana Sayfa Seçenekleri</title><link rel="stylesheet" href="tokens.css"><style>
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);font-size:var(--role-body-size);padding:var(--space-32)}header{max-width:1040px;margin:auto auto var(--space-32)}h1{font-family:GilroyBd;font-size:var(--role-page-size);margin:0 0 var(--space-12)}h2{font-family:GilroyBd;font-size:var(--role-section-size);margin:var(--space-16) 0 var(--space-8)}p{line-height:var(--role-body-line);margin:var(--space-8) 0}a{color:var(--tomato-deep)}.toolbar{display:flex;flex-wrap:wrap;gap:var(--space-12);align-items:center;margin-top:var(--space-16)}select,a.open{border:1px solid var(--line);border-radius:var(--radius-control);padding:var(--space-12);background:var(--paper);font:inherit}main{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-40);max-width:1040px;margin:auto}.phone{box-sizing:content-box;width:var(--viewport,390px);height:844px;max-width:100%;border:1px solid var(--line);border-radius:var(--radius-sheet);overflow:hidden;box-shadow:var(--sh-md);margin:auto;background:var(--paper)}iframe{width:100%;height:100%;border:0}.caption{max-width:430px;margin:auto}.caption dl{font-size:var(--role-meta-size);line-height:var(--role-meta-line)}dt{font-family:GilroyBd;margin-top:var(--space-12)}dd{margin:var(--space-4) 0 0}nav{display:flex;gap:var(--space-12);margin-top:var(--space-16);flex-wrap:wrap}@media(max-width:960px){main{grid-template-columns:1fr}body{padding:var(--space-20)}}
</style></head><body><header><h1>Aynı temel. Üç sade ana sayfa.</h1><p>A + B hibrit hero üçünde de aynı; seçim, altındaki uygulama kurgusu.</p><div class="toolbar"><label>Görünüm <select id="width"><option>360</option><option selected>390</option><option>430</option></select></label><a href="hero-hibrit.html">Hibrit hero'yu aç</a><a href="ana-3.html?devam=ornek">3 · Örnek devam durumu</a></div></header><main>'''
for title,idea,url,removed,added in choices:
 s+=f'<article><div class="phone"><iframe src="{url}" title="{title}" loading="lazy"></iframe></div><div class="caption"><h2>{title}</h2><p>{idea}</p><nav><a class="open" href="{url}">Tek başına aç</a></nav><dl><dt>Mevcut sayfadan ne çıktı?</dt><dd>{removed}</dd><dt>Ne eklendi / değişti?</dt><dd>{added}</dd></dl></div></article>'
s+='</main><script>document.querySelector("#width").onchange=e=>document.documentElement.style.setProperty("--viewport",e.target.value+"px")</script></body></html>'
Path('v3-app/ana-sayfa-secenekleri.html').write_text(s)
